	["Coloured from"] = "Color\195\169 selon",
	["Colours"] = "Couleurs",
	["Colours a debuff timer red below this many seconds. Set to zero to keep one colour."] = "Colore la dur\195\169e d\226\128\153un malus en rouge sous ce nombre de secondes. Z\195\169ro conserve une seule couleur.",
	["Colours an enemy's level number by how hard it is for you."] = "Colore le niveau d'un ennemi selon sa difficult\195\169 pour vous.",
	["Colours bars by their standing, by your class, or with one colour."] = "Colore les barres selon leur niveau de r\195\169putation, votre classe, ou d'une seule couleur.",
	["Colours casts the game marks as important, such as spells that are deadly if not interrupted."] = "Colore les incantations que le jeu marque comme importantes, comme les sorts mortels s'ils ne sont pas interrompus.",
	["Colours each equipment slot's border by its item's quality."] = "Colore la bordure de chaque emplacement d'\195\169quipement selon la qualit\195\169 de son objet.",
	["Colours each loot icon's border by its item's quality."] = "Colore la bordure de chaque ic\195\180ne de butin selon la qualit\195\169 de l'objet.",
	["Colours each player's name in chat with their class colour."] = "Colore le nom de chaque joueur dans la discussion avec sa couleur de classe.",
	["Colours each roll's item border by its quality."] = "Colore la bordure de l'objet de chaque jet selon sa qualit\195\169.",
	["Colours elites above your level."] = "Colore les \195\169lites de niveau sup\195\169rieur au v\195\180tre.",
	["Colours enemies while they cast. Threat on the bar wins unless Threat beats unit types is off."] = "Colore les ennemis pendant leurs incantations. La menace sur la barre de vie prime, sauf si La menace prime sur les types est d\195\169sactiv\195\169.",
	["Colours links and the chat's highlights with your class colour or a colour you pick."] = "Colore les liens et les surbrillances de la discussion avec votre couleur de classe ou une couleur de votre choix.",
	["Colours mobs that leave you alone until you attack them."] = "Colore les monstres qui vous ignorent tant que vous ne les attaquez pas.",
	["Colours names in the text colour, by class or in one colour."] = "Colore les noms dans la couleur du texte, selon la classe ou d'une seule couleur.",
	["Colours ordinary and trivial mobs. The other types win."] = "Colore les monstres ordinaires et triviaux. Les autres types l'emportent.",
	["Colours player names by class and other names by reaction."] = "Colore les noms des joueurs selon la classe et les autres noms selon la r\195\169action.",
	["Colours players' names with their class colour."] = "Colore les noms des joueurs avec leur couleur de classe.",
	["Colours quest titles in quest gold instead of Blizzard's quest colours."] = "Colore les titres de qu\195\170te en or de qu\195\170te au lieu des couleurs de qu\195\170te de Blizzard.",
	["Colours the Alliance or Horde line in its faction colour."] = "Colore la ligne Alliance ou Horde de la couleur de sa faction.",
	["Colours the bar edge instead of glowing around it. Off restores the threat glow."] = "Colore le bord de la barre. D\195\169sactiv\195\169 : r\195\169tablit la lueur de menace.",
	["Colours the border of buttons holding an uncommon or better item."] = "Colore la bordure des boutons contenant un objet inhabituel ou de qualit\195\169 sup\195\169rieure.",
	["Colours the class on a player's level line in the class colour."] = "Colore la classe sur la ligne de niveau d'un joueur avec la couleur de classe.",
	["Colours the clock's AM or PM with the accent."] = "Colore le AM ou PM de l'horloge avec l'accent.",
	["Colours the count red below this many free slots. 0 turns it off."] = "Colore le nombre en rouge sous ce nombre d\226\128\153emplacements libres. 0 le d\195\169sactive.",
	["Colours the difficulty with the accent."] = "Colore la difficult\195\169 avec l'accent.",
	["Colours the fps and ms labels with the accent."] = "Colore les libell\195\169s fps et ms avec l'accent.",
	["Colours the plates of elites and bosses. Off, the gold diamond alone marks them."] = "Colore les barres d'info des \195\169lites et des boss. D\195\169sactiv\195\169, seul le losange dor\195\169 les marque.",
	["Colours the plates of mobs one of your quests needs. Wins over the other types."] = "Colore les barres d'info des monstres dont une de vos qu\195\170tes a besoin. Prime sur les autres types.",
	["Colours the plates of mobs that have mana: the ones that cast and can be interrupted."] = "Colore les barres d'info des monstres qui ont du mana : ceux qui lancent des sorts et peuvent \195\170tre interrompus.",
	["Colours the plates of rare and rare elite mobs."] = "Colore les barres d'info des monstres rares et \195\169lites rares.",
	["Colours the red ring of each debuff by its type, such as magic or poison."] = "Colore l'anneau rouge de chaque affaiblissement selon son type, comme magie ou poison.",
	["Colours the small mobs that come in swarms."] = "Colore les petits monstres qui arrivent en essaims.",
	["Colours the threat percent with the threat colour. Off shows it in white."] = "Colore le pourcentage de menace avec la couleur de menace. D\195\169sactiv\195\169, il est blanc.",
	["Colours the unit's level from grey for trivial to red for far above you."] = "Colore le niveau de l'unit\195\169, du gris pour insignifiant au rouge pour bien au-dessus de vous.",
	["Colours the zone name plainly, by PvP status or with the accent."] = "Colore le nom de la zone simplement, selon le statut JcJ ou avec l'accent.",
	["Colours world bosses and skull-level mobs. Wins over rares and elites."] = "Colore les boss mondiaux et les monstres de niveau cr\195\162ne. Prioritaire sur rares et \195\169lites.",
	["Colours your group's names inside say, yell, party, raid and instance messages."] = "Colore les noms de votre groupe dans les messages dire, crier, groupe, raid et instance.",
