	["Drawer spacing"] = "Espacement du tiroir",
	["Draws a KstyleUI glass panel behind the tracker."] = "Dessine un panneau de verre KstyleUI derri\195\168re le suivi.",
	["Draws a border in the threat colour around members with aggro."] = "Dessine une bordure de la couleur de menace autour des membres qui ont l'aggro.",
	["Draws a gilt line under the tooltip's title."] = "Dessine une ligne dor\195\169e sous le titre de la bulle d'aide.",
	["Draws a glow and an edge around your target's plate."] = "Dessine une lueur et un bord autour de la barre d'info de votre cible.",
	["Draws a grid in Layout Mode, and elements snap to its lines."] = "Dessine une grille en mode Disposition ; les \195\169l\195\169ments s'aimantent \195\160 ses lignes.",
	["Draws a soft shadow around KstyleUI's panels, windows and tooltips."] = "Dessine une ombre douce autour des panneaux, fen\195\170tres et bulles d'aide de KstyleUI.",
	["Draws a soft shadow around the chat panel."] = "Dessine une ombre douce autour du panneau de discussion.",
