	["Draws debuffs over neighbouring plates."] = "Dessine les affaiblissements par-dessus les barres voisines.",
	["Draws enemy plates larger while they cast. 1 keeps their size."] = "Agrandit les barres ennemies pendant leurs incantations. 1 garde leur taille.",
