	["Draws every unit frame cast bar above other frames so nothing covers it."] = "Dessine chaque barre d'incantation des cadres d'unit\195\169 au-dessus des autres cadres pour que rien ne la cache.",
	["Draws shields after the health, or back from the bar's end."] = "Dessine les boucliers apr\195\168s la sant\195\169, ou depuis la fin de la barre.",
	["Draws smoked glass behind the buttons."] = "Dessine du verre fum\195\169 derri\195\168re les boutons.",
	["Draws the chamfered frame around the bar."] = "Dessine le cadre biseaut\195\169 autour de la barre.",
	["Draws the part of a shield larger than the missing health back over the health, from the bar's end."] = "Dessine la part d'un bouclier qui d\195\169passe la sant\195\169 manquante par-dessus la sant\195\169, depuis la fin de la barre.",
	["Draws the strip on smoked glass."] = "Dessine le bandeau sur du verre fum\195\169.",
