	["Duration"] = "Dur\195\169e",
	["Duration swipe"] = "Balayage de dur\195\169e",
	["Each buff keeps its own slot, leaving a gap while it is off you."] = "Chaque am\195\169lioration garde sa place et laisse un vide tant qu'elle n'est pas sur vous.",
	["Each character keeps its own pins, starting from the shared ones."] = "Chaque personnage garde ses propres \195\169pingles, \195\160 partir de celles partag\195\169es.",
	["Each window's last lines come back after a reload or relog. Turning this off forgets them."] = "Les derni\195\168res lignes de chaque fen\195\170tre reviennent apr\195\168s un rechargement ou une reconnexion. D\195\169sactiver les oublie.",
	["Ease mouse wheel zoom and pan. Off restores instant zoom in full steps."] = "Adoucit le zoom \195\160 la molette et le d\195\169placement. D\195\169sactiv\195\169 : zoom imm\195\169diat par paliers.",
	["Ease the fill to a new value instead of snapping."] = "Fait glisser le remplissage vers sa nouvelle valeur au lieu de sauter.",
	["Edges buffs that have a dispel type in its colour, such as magic buffs you can purge."] = "Borde les am\195\169liorations ayant un type de dissipation de sa couleur, comme la magie que vous pouvez purger.",
	["Edges debuffs in their dispel type's colour."] = "Borde les affaiblissements de la couleur de leur type de dissipation.",
