	["How far right of the mouse the tooltip sits."] = "\195\128 quelle distance \195\160 droite de la souris se place la bulle d'aide.",
	["How far the idle chat fades. 1 hides it until it wakes."] = "Jusqu'o\195\185 la discussion au repos s'estompe. 1 la masque jusqu'\195\160 son r\195\169veil.",
	["How far the selected tab's tile reaches past its name, up to half the tab spacing."] = "Jusqu'o\195\185 la tuile de l'onglet choisi d\195\169passe son nom, au plus la moiti\195\169 de l'espacement.",
	["How far your numbers move in their field above your character, up to the field's height."] = "Jusqu'o\195\185 vos chiffres se d\195\169placent dans leur zone au-dessus de votre personnage, au plus la hauteur de la zone.",
