	["How many rows of icons show before the rest count as +N on the last icon."] = "Combien de rang\195\169es d'ic\195\180nes s'affichent avant que le reste ne compte comme +N sur la derni\195\168re ic\195\180ne.",
	["How many rows show before the grid or the sections scroll; 0 fits the screen."] = "Nombre de rang\195\169es affich\195\169es avant que la grille ou les sections d\195\169filent ; 0 s'adapte \195\160 l'\195\169cran.",
