	["Items this search matches fill the section: & both, | either, ! not, type:, ilvl>30, junk, bound."] = "Les objets qui correspondent \195\160 cette recherche remplissent la section : & les deux, | l'un ou l'autre, ! non, type:, ilvl>30, junk, bound.",
