	["Keep"] = "Garder",
	["Keep Medallions name face"] = "Conserver la police des noms Medallions",
	["Keep a dimmed icon while the buff is off you. Active buffs come first."] = "Garde une ic\195\180ne assombrie quand l'am\195\169lioration ne vous affecte pas. Les am\195\169liorations actives passent en premier.",
