	["Keep buffs in place"] = "Garder les am\195\169liorations en place",
	["Keep casting units at full opacity"] = "Garder les unit\195\169s qui incantent opaques",
	["Keep chat across sessions"] = "Garder la discussion entre les sessions",
	["Keep chat tabs visible, underline their names and leave room above the first message."] = "Garde les onglets visibles, souligne les noms et espace le premier message.",
	["Keep combat text clear"] = "D\195\169gager le texte de combat",
	["Keep focus at full opacity"] = "Garder le focus enti\195\168rement opaque",
	["Keep gold on hand"] = "Garder de l'or sur soi",
	["Keep hairlines quiet, or use your class colour or a colour you pick."] = "Garder des bordures discr\195\168tes, ou utiliser la couleur de votre classe ou une couleur de votre choix.",
	["Keep map plaques clear"] = "D\195\169gager les plaques de carte",
