	["Keep my UI"] = "Garder mon interface",
	["Keep raid tools available"] = "Garder les outils de raid disponibles",
	["Keep round-map labels below the screen edge and clear of the ring. Off uses the old positions."] = "\195\137carter les titres du bord et de l'anneau. D\195\169sactiv\195\169 : positions pr\195\169c\195\169dentes.",
	["Keep rows by the HUD. Turn off for the previous placement. Custom positions are kept."] = "Rang\195\169es pr\195\168s du HUD. D\195\169sactiver pour les anciennes positions. Vos positions sont conserv\195\169es.",
	["Keep settings text readable"] = "Garder un texte lisible",
	["Keep text above the reading floor when shrinking this window. Off keeps the previous scaling."] = "Garde une taille lisible quand la fen\195\170tre r\195\169tr\195\169cit. D\195\169sactiv\195\169 conserve l\226\128\153ancienne \195\169chelle.",
	["Keep the current outline's shadow, or show or hide it explicitly."] = "Conserver l\226\128\153ombre du contour actuel, ou choisir de l\226\128\153afficher ou de la masquer.",
	["Keep the current style, or choose class, reaction, accent or a custom colour."] = "Garde le style actuel ou choisit la classe, la r\195\169action, l'accent ou une couleur personnalis\195\169e.",
	["Keep the envelope in the column, or in a corner of the map."] = "Garder l'enveloppe dans la colonne, ou dans un coin de la carte.",
	["Keep the layout and leave Layout Mode."] = "Garder la disposition et quitter le mode Disposition.",
	["Keep the portrait level and leave room for names. Off repeats the level beside the name."] = "Garde le niveau sur le portrait et lib\195\168re les noms. D\195\169sactiver r\195\169p\195\168te le niveau pr\195\168s du nom.",
	["Keep the power bar's room"] = "Garder la place de la barre de ressource",
	["Keep these cooldowns in colour while cooling and these buffs while off you."] = "Garde ces recharges en couleur pendant la recharge et ces am\195\169liorations absentes.",
	["Keep these in colour"] = "Garder ceux-ci en couleur",
	["Keep these in full colour while you lack the resource."] = "Garde ceux-ci en pleine couleur quand la ressource vous manque.",
	["Keep titles in player names. Off shows the character name alone."] = "Conserve les titres des joueurs. Sinon, seul le nom du personnage est affich\195\169.",
	["Keep window borders and chat tab underlines on whole pixels. Off restores their original placement."] = "Aligne les bordures des fen\195\170tres et les soulignements des onglets de discussion sur les pixels. D\195\169sactiv\195\169, r\195\169tablit leur position initiale.",
	["Keep your row visible when it falls outside the meter's visible rows."] = "Garder votre ligne visible lorsqu\226\128\153elle sort des lignes visibles du compteur.",
	["Keeps Blizzard's icon colours, or tints the icons in the accent colour or white."] = "Garde les couleurs d'ic\195\180nes de Blizzard, ou teinte les ic\195\180nes dans la couleur d'accent ou en blanc.",
	["Keeps casting units visible when other plates are dimmed."] = "Garde les unit\195\169s qui incantent visibles lorsque les autres barres sont att\195\169nu\195\169es.",
	["Keeps danger at the edges and hides it with the UI. Off restores the original red glow."] = "Danger sur les bords, masqu\195\169 avec l\226\128\153interface. D\195\169sactiv\195\169 : lueur rouge d\226\128\153origine.",
	["Keeps failed casts readable and acknowledges channels. Off restores the original cast effects."] = "Maintient les \195\169checs et confirme les canalisations. D\195\169sactiv\195\169 : effets d\226\128\153origine.",
	["Keeps other plates quiet while showing the spell your target or focus is casting."] = "Affiche le sort de votre cible ou focalisation en gardant les autres barres discr\195\168tes.",
	["Keeps position and size details visible on every Layout Mode plate."] = "Garde la position et la taille visibles sur chaque plaque du mode Disposition.",
	["Keeps the HUD at its previous size until 120 ms after the last window resize."] = "Conserve la taille pr\195\169c\195\169dente de l\226\128\153ATH jusqu\226\128\153\195\160 120 ms apr\195\168s le dernier redimensionnement de la fen\195\170tre.",
	["Keeps the current style, colours the level by how hard the unit is, or uses your own colour."] = "Garde le style actuel, colore le niveau selon la difficult\195\169 de l'unit\195\169 ou utilise votre couleur.",
	["Keeps the game's raid controls available. Off restores the previous hidden raid manager."] = "Garde les contr\195\180les de raid accessibles. D\195\169sactiv\195\169 : gestionnaire de raid masqu\195\169 comme auparavant.",
	["Keeps the last fight's time on screen after combat."] = "Garde la dur\195\169e du dernier combat \195\160 l'\195\169cran apr\195\168s le combat.",
	["Keeps your account's gold for the last seven days you played and shows the change in the tooltip."] = "Garde l\226\128\153or de votre compte pour les sept derniers jours jou\195\169s et affiche l\226\128\153\195\169volution dans l\226\128\153infobulle.",
	["Keeps your focus visible when other plates are dimmed."] = "Garde votre focus visible lorsque les autres barres sont att\195\169nu\195\169es.",
	["Key ring"] = "Trousseau de cl\195\169s",
	["Keybind text"] = "Texte des raccourcis",
	["Keybinding mode closed for combat. Unsaved bindings were discarded."] = "Le mode de raccourcis a \195\169t\195\169 ferm\195\169 pour le combat. Les raccourcis non enregistr\195\169s ont \195\169t\195\169 annul\195\169s.",
	["Keybinding mode is unavailable on this client."] = "Le mode de raccourcis est indisponible sur ce client.",
