	["KstyleUI leaves the RestedXP guide where you put it. Turn Story rail back on in the RestedXP skin's settings."] = "KstyleUI laisse le guide RestedXP l\195\160 o\195\185 vous l'avez mis. R\195\169activez la colonne R\195\169cit dans les r\195\169glages de l'habillage RestedXP.",
