	["Shows KstyleUI's micro menu in place of Blizzard's. Off, Blizzard's returns."] = "Affiche le micro-menu de KstyleUI \195\160 la place de celui de Blizzard. D\195\169sactiv\195\169, celui de Blizzard revient.",
