	["Shows Zz while you rest in an inn or a city."] = "Affiche Zz quand vous vous reposez dans une auberge ou une ville.",
	["Shows a LibDataBroker plugin from another addon."] = "Affiche un module LibDataBroker d\226\128\153un autre addon.",
	["Shows a bar for your main-hand swings."] = "Affiche une barre pour vos attaques de la main droite.",
