	["Shows a bar for your ranged attacks."] = "Affiche une barre pour vos attaques \195\160 distance.",
	["Shows a button on the damage meter's title that clears every fight, after combat."] = "Affiche dans le titre du compteur un bouton qui efface tous les combats, apr\195\168s le combat.",
	["Shows a card of the spells you cast last, like the damage meter. Move it in Layout Mode."] = "Affiche une carte de vos derniers sorts, comme le compteur. D\195\169placez-la en Mode Disposition.",
	["Shows a crown when the unit leads the group."] = "Affiche une couronne quand l'unit\195\169 m\195\168ne le groupe.",
	["Shows a debuff's tooltip when you point at its icon."] = "Affiche l'infobulle d'un affaiblissement quand vous pointez son ic\195\180ne.",
	["Shows a debuff's tooltip while you hover it. The plate behind the icon does not take the mouse."] = "Affiche l'infobulle d'un affaiblissement au survol. La barre derri\195\168re l'ic\195\180ne ne re\195\167oit pas la souris.",
	["Shows a faction badge after the names of units flagged for PvP."] = "Affiche un badge de faction apr\195\168s le nom des unit\195\169s en JcJ.",
	["Shows a few debuffs on each frame."] = "Affiche quelques affaiblissements sur chaque cadre.",
	["Shows a heal's tooltip when you point at its icon."] = "Affiche l'infobulle d'un soin quand vous pointez son ic\195\180ne.",
	["Shows a player's buffs as icons beside the tooltip whenever the game shares them."] = "Affiche les am\195\169liorations d'un joueur en ic\195\180nes \195\160 c\195\180t\195\169 de l'infobulle, quand le jeu les communique.",
	["Shows a player's guild in angle brackets, green for your own guild."] = "Affiche la guilde d'un joueur entre chevrons, en vert pour votre propre guilde.",
