	["Shows a strip of the spells you cast last. Move it in Layout Mode."] = "Affiche une bande de vos derniers sorts. D\195\169placez-la en Mode Disposition.",
	["Shows a thin mana, rage or energy bar under the health bar."] = "Affiche une fine barre de mana, de rage ou d'\195\169nergie sous la barre de vie.",
	["Shows absorb shields when incoming heals are enabled."] = "Affiche les boucliers d\226\128\153absorption si les soins entrants sont activ\195\169s.",
	["Shows all your profiles, character and specialization choices, account preferences and profile hotkeys as one string to copy."] = "Affiche tous vos profils, choix de personnage et de sp\195\169cialisation, pr\195\169f\195\169rences du compte et raccourcis de profil en une cha\195\174ne \195\160 copier.",
	["Shows an envelope while you have unread mail."] = "Affiche une enveloppe quand vous avez du courrier non lu.",
	["Shows an eye while you are queued, in place of Blizzard's queue eye."] = "Affiche un \197\147il quand vous \195\170tes en file d'attente, \195\160 la place de l'\197\147il de Blizzard.",
	["Shows an item, spell or quest tooltip while the pointer is over its link in chat."] = "Affiche l'infobulle d'un objet, d'un sort ou d'une qu\195\170te quand le pointeur survole son lien.",
	["Shows another damage meter with its own Show and Fight. Move it in Layout Mode."] = "Affiche un autre compteur de d\195\169g\195\162ts avec ses propres Afficher et Combat. D\195\169placez-le en Mode Disposition.",
	["Shows combo points and the druid's mana under the player frame."] = "Affiche les points de combo et le mana du druide sous le cadre du joueur.",
	["Shows crossed swords on members who are in combat."] = "Affiche des \195\169p\195\169es crois\195\169es sur les membres en combat.",
