	["Shows each share of the total, when the game lets addons read it."] = "Affiche chaque part du total, quand le jeu permet aux add-ons de la lire.",
	["Shows experience, or watched reputation at the level cap."] = "Affiche l'exp\195\169rience, ou la r\195\169putation suivie au niveau maximal.",
	["Shows frames per second and latency on the map."] = "Affiche les images par seconde et la latence sur la carte.",
	["Shows guild members online. Hidden when you have no guild."] = "Affiche les membres de guilde en ligne. Masqu\195\169 sans guilde.",
	["Shows health as a percent, a value, or both."] = "Affiche la vie en pourcentage, en valeur, ou les deux.",
	["Shows health percentages with one decimal place. Shortened health values already show one."] = "Affiche les pourcentages de vie avec une d\195\169cimale. Les valeurs de vie abr\195\169g\195\169es en ont d\195\169j\195\160 une.",
	["Shows honour only in battlegrounds and world PvP, or all the time."] = "Affiche l'honneur seulement en champs de bataille et en JcJ sauvage, ou tout le temps.",
	["Shows how far your rested experience reaches past your current experience."] = "Montre jusqu'o\195\185 votre exp\195\169rience de repos va au-del\195\160 de votre exp\195\169rience actuelle.",
	["Shows how long KstyleUI takes each frame, refreshed while this page is open."] = "Indique le temps pris par KstyleUI \195\160 chaque image, actualis\195\169 tant que cette page est ouverte.",
	["Shows how long the current or last fight lasted."] = "Affiche la dur\195\169e du combat en cours ou du dernier.",
	["Shows how long you have been in combat. Move it in Layout Mode."] = "Affiche depuis combien de temps vous combattez. D\195\169placez-le en Mode Disposition.",
