	["The system buttons under the readout. Off, the card is one line; keybinds and Escape still work."] = "Les boutons syst\195\168me sous l'affichage. D\195\169sactiv\195\169, la carte tient sur une ligne ; les raccourcis et \195\137chap marchent toujours.",
	["The tallest the bag and bank windows grow, as a percentage of the screen's height."] = "La hauteur maximale des fen\195\170tres de sacs et de banque, en pourcentage de l'\195\169cran.",
	["The target highlight follows the accent or uses your own colour."] = "La mise en \195\169vidence de la cible suit l'accent ou utilise votre propre couleur.",
	["The target ring's thickness: two lines or one."] = "L'\195\169paisseur de l'anneau de cible : deux lignes ou une.",
	["The text colour when its colour mode is custom."] = "La couleur du texte en mode personnalis\195\169.",
	["The text size in KstyleUI units; Appearance's text size scales it too."] = "La taille du texte en unit\195\169s KstyleUI ; la taille du texte d'Apparence la met aussi \195\160 l'\195\169chelle.",
	["The text size of numbers on party and raid frames."] = "La taille du texte des chiffres sur les cadres de groupe et de raid.",
