	["The text size of the stack counts."] = "La taille du texte des cumuls.",
	["The text size of the timers."] = "La taille du texte des minuteurs.",
	["The texture of the health and power bars."] = "La texture des barres de vie et de ressource.",
	["The texture the bar is filled with."] = "La texture dont la barre est remplie.",
	["The threat percentage that turns the meter red and makes it pulse."] = "Le pourcentage de menace qui fait passer le compteur au rouge et le fait pulser.",
	["The threat percentage that turns the meter yellow."] = "Le pourcentage de menace qui fait passer le compteur au jaune.",
	["The tint of a spell whose target is out of range."] = "La teinte d'un sort dont la cible est hors de port\195\169e.",
	["The tooltip accent when Accent colour is set to custom."] = "L'accent des bulles d'aide quand Couleur d'accent est r\195\169gl\195\169e sur personnalis\195\169.",
	["The travel menu will be ready after combat."] = "Le menu de voyage sera pr\195\170t apr\195\168s le combat.",
	["The typeface for these lines while Use KstyleUI's font is off."] = "La police de ces lignes quand Utiliser la police KstyleUI est d\195\169sactiv\195\169.",
	["The typeface of the %s."] = "La police pour %s.",
	["The typeface of the numbers."] = "La police des chiffres.",
	["The typeface of the stack counts on the icons."] = "La police des cumuls sur les ic\195\180nes.",
	["The typeface of the text. The interface font follows the Appearance page."] = "La police du texte. La police de l'interface suit la page Apparence.",
	["The typeface of the timers."] = "La police des minuteurs.",
	["The value alone, or with your level or the faction."] = "La valeur seule, ou avec votre niveau ou la faction.",
	["The vertical line's thickness in pixels; zero follows the style."] = "\195\137paisseur de la ligne verticale en pixels ; z\195\169ro suit le style.",
	["The way Sort packs items across your bags."] = "La fa\195\167on dont Trier range les objets dans vos sacs.",
	["The way the grid fills from its first slot."] = "La fa\195\167on dont la grille se remplit \195\160 partir de son premier emplacement.",
	["The whole chat fades after a quiet spell. Hovering, typing or new player chat brings it back."] = "La discussion s'estompe apr\195\168s un moment calme. Le survol, la saisie ou un message de joueur la ram\195\168ne.",
	["The width and height of each button in the column."] = "La largeur et la hauteur de chaque bouton de la colonne.",
	["The width and height of each icon."] = "La largeur et la hauteur de chaque ic\195\180ne.",
	["The width of each bar, icon included."] = "La largeur de chaque barre, ic\195\180ne comprise.",
	["The width of the health bar, in interface units."] = "La largeur de la barre de vie, en unit\195\169s d\226\128\153interface.",
	["The width the location keeps when it is fixed."] = "La largeur que garde le lieu quand elle est fixe.",
	["The window shrinks as soon as it needs less room. Off keeps its size until you close it."] = "La fen\195\170tre se r\195\169duit d\195\168s qu'elle a besoin de moins de place. D\195\169sactiv\195\169 garde sa taille jusqu'\195\160 la fermeture.",
	["The zoom slider's fill and the active buttons follow your class colour or your own colour."] = "Le remplissage du curseur de zoom et les boutons actifs suivent votre couleur de classe ou votre propre couleur.",
	["There is no profile named %s."] = "Il n'existe aucun profil nomm\195\169 %s.",
	["Thick"] = "\195\137pais",
	["Thick outline"] = "Contour \195\169pais",
	["Thin"] = "Fin",
	["Thin gilt rails and plain pointed ends on frames, bars and nameplates, with small arrow caps beside the action bars."] = "Fins rails dor\195\169s et extr\195\169mit\195\169s pointues simples sur les cadres, les barres et les barres de nom, avec de petites pointes de fl\195\168che \195\160 c\195\180t\195\169 des barres d\226\128\153action.",
	["Thin outline"] = "Contour fin",
	["This account string is not valid."] = "Cette cha\195\174ne de compte n'est pas valide.",
