	["This profile string is damaged or incomplete. Copy the whole string and try again."] = "Cette cha\195\174ne de profil est endommag\195\169e ou incompl\195\168te. Copiez la cha\195\174ne enti\195\168re et r\195\169essayez.",
	["This profile string is too large."] = "Cette cha\195\174ne de profil est trop volumineuse.",
