	["This profile string was made with C_EncodingUtil, which this game client does not have."] = "Cette cha\195\174ne de profil a \195\169t\195\169 cr\195\169\195\169e avec C_EncodingUtil, que ce client de jeu n'a pas.",
	["This profile's specialization or Edit Mode part is not valid."] = "La partie sp\195\169cialisation ou mode \195\137dition de ce profil n'est pas valide.",
