	["Try again"] = "R\195\169essayer",
	["Tune each action bar with its own tab for text, cooldowns, quality borders and show/hide rules."] = "R\195\169glez chaque barre d'actions dans son propre onglet : texte, temps de recharge, bordures de qualit\195\169 et r\195\168gles d'affichage.",
	["Turn on the Cooldown Manager in %s to see the restyled cooldowns."] = "Activez le gestionnaire de temps de recharge dans %s pour voir les temps de recharge restyl\195\169s.",
	["Turn this frame off to leave its unit without a KstyleUI frame."] = "D\195\169sactivez ce cadre pour laisser son unit\195\169 sans cadre KstyleUI.",
	["Turns Blizzard's gold and white lines into KstyleUI's greys. Coloured lines stay."] = "Transforme les lignes dor\195\169es et blanches de Blizzard en gris KstyleUI. Les lignes color\195\169es restent.",
	["Turns the map so you always face up, and hides the N. Off leaves the game's own setting alone."] = "Fait pivoter la carte pour toujours regarder vers le haut et masque le N. D\195\169sactiv\195\169, le jeu d\195\169cide.",
	["Turns these game plates on or off. The game's setting leaves them alone."] = "Active ou d\195\169sactive ces barres d'info du jeu. R\195\169glage du jeu n'y touche pas.",
	["Turns this bar on or off."] = "Active ou d\195\169sactive cette barre.",
	["Turns this bar on or off. Beside the party frames it lowers the largest HUD size."] = "Active ou d\195\169sactive cette barre. \195\128 c\195\180t\195\169 des cadres de groupe, elle r\195\169duit la taille maximale du HUD.",
	["Turns this module on or off."] = "Active ou d\195\169sactive ce module.",
	["Turns web addresses into links. Click one to copy it."] = "Transforme les adresses web en liens. Cliquez sur l'un d'eux pour le copier.",
	["Two movable anchors; attach your own auras to KstyleUI_WeakAuras1 and KstyleUI_WeakAuras2."] = "Deux ancres mobiles ; attachez vos auras \195\160 KstyleUI_WeakAuras1 et KstyleUI_WeakAuras2.",
	["Two rows on the slab"] = "Deux rang\195\169es sur la plaque",
	["Two-Hand"] = "Deux mains",
	["Type /kb to hover a button and press a key to bind it. Save for your account or this character, or Discard your changes."] = "Tapez /kb, survolez un bouton et appuyez sur une touche pour l'attribuer. Enregistrez pour le compte ou ce personnage, ou annulez les changements.",
