	["Uses 35 percent opacity and label tags on movers. Off restores the old solid plates."] = "Utilise des cadres sombres \195\160 35 pour cent avec \195\169tiquettes. D\195\169sactiv\195\169 : anciens cadres opaques.",
	["Uses a dark metal rim around aura tiles in Medallions. Off restores the black rim."] = "Utilise un bord m\195\169tallique sombre pour les auras des m\195\169daillons. D\195\169sactiv\195\169 : bord noir.",
	["Uses distinct role symbols on compact frames. Off restores the coloured pips."] = "Utilise des symboles de r\195\180le distincts sur les cadres compacts. D\195\169sactiv\195\169 : points color\195\169s.",
	["Uses the action slab's metal frame for cooldown and tracked buff icons in Medallions."] = "Utilise le cadre m\195\169tallique de la barre pour les recharges et am\195\169liorations des m\195\169daillons.",
	["Uses the number font for debuff timers and stacks. Turn off to use the plate font."] = "Utilise la police des nombres pour la dur\195\169e et les cumuls des malus. D\195\169sactivez pour utiliser la police des barres.",
	["Uses the other element's height within this element's size limits."] = "Utilise la hauteur de l\226\128\153autre \195\169l\195\169ment dans les limites de taille de celui-ci.",
