	["Uses the role font unless you choose a font for this text."] = "Utilise la police du r\195\180le, sauf si vous choisissez une police pour ce texte.",
	["Uses the same bare seconds and minute labels as action buttons."] = "Utilise les m\195\170mes secondes sans suffixe et minutes que les boutons d\226\128\153action.",
