	["Welcome"] = "Bienvenue",
	["Welcome text, the French and German Options footer, the 1080p data bar and colour-vision health bars read right."] = "Le texte d'accueil, le pied de page fran\195\167ais et allemand des options, la barre de donn\195\169es en 1080p et les barres de vie pour daltoniens s'affichent correctement.",
	["Welcome to KstyleUI"] = "Bienvenue dans KstyleUI",
	["What happens when you learn a higher rank of a spell on your bars."] = "Ce qui se passe quand vous apprenez un rang sup\195\169rieur d'un sort pr\195\169sent sur vos barres.",
