	["What the health text shows."] = "Ce qu'affiche le texte de vie.",
	["What the text on the bar says."] = "Ce que dit le texte sur la barre.",
	["What the window measures. Click its title to switch between damage and healing in game."] = "Ce que la fen\195\170tre mesure. Cliquez sur son titre en jeu pour passer des d\195\169g\195\162ts aux soins.",
	["What this indicator shows; slots sharing a place sit side by side."] = "Ce que montre cet indicateur ; les emplacements au m\195\170me endroit se placent c\195\180te \195\160 c\195\180te.",
	["What your bags do when this window opens and closes. Closing only closes bags it opened."] = "Ce que font vos sacs \195\160 l'ouverture et la fermeture de cette fen\195\170tre. Elle ne ferme que ceux qu'elle a ouverts.",
	["What's new"] = "Nouveaut\195\169s",
	["Wheel between maps"] = "Changer de carte \195\160 la molette",
	["Wheel out past a map's edge to its parent, or in over a zone to open it."] = "D\195\169zoomez \195\160 la limite pour ouvrir la carte parente, ou zoomez sur une zone pour l\226\128\153ouvrir.",
	["When a condition matches"] = "Si une condition est remplie",
	["When all layouts are full, choose one to replace. Off keeps the previous full-list message."] = "Si tous les emplacements sont pris, choisissez un remplacement. D\195\169sactiv\195\169 : ancien message de liste pleine.",
	["When hovering a button shows its tooltip."] = "Quand le survol d'un bouton affiche sa bulle d'aide.",
	["When hovering a unit frame shows the unit's tooltip."] = "Quand le survol d'un cadre d'unit\195\169 affiche l'infobulle de l'unit\195\169.",
	["When hovering an icon shows its tooltip."] = "Quand le survol d'une ic\195\180ne affiche son infobulle.",
	["When solo only"] = "En solo seulement",
	["When the colours are close, draws power in steel with a thin line of its original colour."] = "Si les couleurs sont proches, affiche la ressource en acier avec un fin trait de sa couleur d\226\128\153origine.",
	["When the crosshair shows."] = "Quand le r\195\169ticule s'affiche.",
	["When the cursor ring shows."] = "Quand l'anneau du curseur s'affiche.",
	["When the element shows."] = "Quand l'\195\169l\195\169ment s'affiche.",
	["When the game auto loots, take every item the moment the window opens."] = "Quand le jeu fouille automatiquement, prend tout d\195\168s l'ouverture de la fen\195\170tre.",
	["When the member's tooltip shows as you point at a frame."] = "Quand l'infobulle du membre s'affiche en pointant un cadre.",
	["When these hide, the icons after them move up, even with Close gaps off."] = "Quand ceux-ci se cachent, les ic\195\180nes suivantes avancent, m\195\170me si Combler les vides est d\195\169sactiv\195\169.",
	["Where a short row starts."] = "O\195\185 commence une rang\195\169e incompl\195\168te.",
	["Where each debuff's stacks sit."] = "L'emplacement des cumuls de chaque affaiblissement.",
	["Where each debuff's time left sits."] = "L'emplacement du temps restant de chaque affaiblissement.",
	["Where each value sits in its cell. One line sizes each readout to its text."] = "La position de chaque valeur dans sa cellule. Sur une ligne, chaque indicateur prend la taille de son texte.",
	["Where it sits inside the map's edge."] = "O\195\185 il se place \195\160 l'int\195\169rieur du bord de la carte.",
	["Where numbers show"] = "O\195\185 s'affichent les chiffres",
	["Where on the frame the indicator sits."] = "O\195\185 se place l'indicateur sur le cadre.",
