	["Where on the icon the stack count sits: in a corner, on an edge or in the centre."] = "L'endroit de l'ic\195\180ne o\195\185 se trouve le nombre de cumuls : dans un coin, sur un bord ou au centre.",
	["Where the bar's colour comes from."] = "D'o\195\185 vient la couleur de la barre.",
