	["Where the glow colour comes from."] = "D'o\195\185 vient la couleur de lueur.",
	["Where the swipe tint comes from."] = "D'o\195\185 vient la teinte du balayage.",
	["Where the text sits around the bar."] = "O\195\185 se place le texte autour de la barre.",
	["Where the threat percent sits inside the health bar."] = "Position du pourcentage de menace dans la barre de vie.",
	["Where the time sits in its frame."] = "La position du temps dans son cadre.",
	["Where the tooltip opens beside the mouse."] = "L'endroit o\195\185 l'infobulle s'ouvre \195\160 c\195\180t\195\169 de la souris.",
	["Where this text sits on the frame."] = "La position de ce texte sur le cadre.",
	["Wherever KstyleUI shows this class colour; the accent keeps its own setting."] = "Partout o\195\185 KstyleUI affiche cette couleur de classe ; l'accent garde son propre r\195\169glage.",
	["Whether buttons fill each row or each column first."] = "Si les boutons remplissent d'abord chaque rang\195\169e ou chaque colonne.",
