	["Whether new bars stack upward or downward."] = "Si les nouvelles barres s'empilent vers le haut ou vers le bas.",
	["Whether rows of debuffs stack upward above the name or downward under the cast bar."] = "Si les rang\195\169es d'affaiblissements s'empilent vers le haut au-dessus du nom ou vers le bas sous la barre de sort.",
